using System.Globalization;
using System.Net;
using System.Text;
using System.Text.Json;
using ClosedXML.Excel;
using Metarill.Core.Contracts;
using Metarill.Runtime.Exports;
using Metarill.Runtime.Persistence;
using Xunit;
namespace Metarill.Generation.Tests;

public sealed partial class FreshGlobalMultipleMySqlTests
{
    private const string Shared="gs_single_shared",Tenant="gs_single_tenant",Original="甲_%!引号'记录",Second="乙记录";
    /// <summary>全部数据只写新租约库；共享值故意来自另一项目，普通目标和来源仍隔离。</summary>
    private static async Task SeedCross(Probe p)
    {
        foreach(var offset in new[]{0,1,2})await p.Store.InsertAsync("gs_single_parent",Row("id",Parent+offset,"name","来源父"+offset,"yz_project_id",offset==2?Project+1:Project));
        foreach(var(index,name,status,segment)in new[]{(0,Original,1,1),(1,Second,1,1),(2,"停用记录",0,1),(3,"另一组记录",1,2),(4,"删除记录",1,1),(5,"重复名",1,1),(6,"重复名",1,1)}){var row=Row("id",First+index,"name",name,"score",1.25m+index,"status",status,"segment",segment);if(!p.NoProject)row["yz_project_id"]=Project+1;if(index==4)row["delete_no"]=DateTime.UtcNow;await p.Store.InsertAsync(Shared,row);}
        foreach(var offset in new[]{0,1})await p.Store.InsertAsync(Tenant,Row("id",First+10000+offset,"name",offset==0?"项目候选":"外项目候选","yz_project_id",offset==0?Project:Project+1,"status",1,"segment",1));
        await p.Store.InsertAsync(p.Source,Row("id",First+900000,"name","外项目来源","yz_project_id",Project+1,"parent_id",Parent,"segment",1,"shared_ids",JsonSerializer.Serialize(new[]{Id(First)}),"checked_ids",JsonSerializer.Serialize(new[]{Id(First)})));
    }
    /// <summary>原多选、复选、数组存储、导入导出、撤权和晚期文件失败均经真实Production/Web。</summary>
    private static async Task VerifyCross(Probe p)
    {
        var shared=new[]{Id(First+1),Id(First)};var checkedIds=new[]{Id(First),Id(First+1)};var name=Original;
        async Task<JsonElement> Checkbox(HttpStatusCode expected=HttpStatusCode.OK,int segment=1)=>await p.Post("findNameIdChecked2204",new{parentId=p.ParentId,formParameters=new{segment}},expected);
        async Task<JsonElement> Selected(HttpStatusCode expected=HttpStatusCode.OK)=> (await p.Send(p.Reader,HttpMethod.Post,"/api/admin/auto/"+Shared+"/302/selection/selected",new{selectedIds=shared},expected)).GetProperty(expected==HttpStatusCode.OK?"data":"code");
        var options=await Checkbox();Assert.Equal(4,options.GetArrayLength());Assert.Contains(options.EnumerateArray(),x=>x.GetProperty("id").GetString()==Id(First));Assert.Equal(Id(First+3),Assert.Single((await Checkbox(segment:2)).EnumerateArray()).GetProperty("id").GetString());var selected=await Selected();Assert.Equal(shared,selected.EnumerateArray().Select(x=>x.GetProperty("id").GetString()));
        var exact=(await p.Send(p.Reader,HttpMethod.Post,"/api/admin/auto/"+Shared+"/302/page",new PageRequest{PageSize=1,Filters=new(){{"name",JsonSerializer.SerializeToElement(Original)}}})).GetProperty("data");Assert.Equal("1",exact.GetProperty("total").GetString());Assert.Equal(Id(First),Assert.Single(exact.GetProperty("records").EnumerateArray()).GetProperty("id").GetString());
        var tenant=(await p.Send(p.Reader,HttpMethod.Post,"/api/admin/auto/"+Tenant+"/402/page",new PageRequest{PageSize=10})).GetProperty("data");Assert.Equal("1",tenant.GetProperty("total").GetString());
        var bytes=Encoding.UTF8.GetBytes("全局多值原文件");var file=await p.Upload(bytes);var added=await p.Post("add",new{name="全局多值来源",sharedIds=shared,checkedIds,tenantIds=new[]{Id(First+10000)},segment=1,attachments=new[]{file}});p.RecordId=added.GetProperty("id").GetString()!;Check(added);await p.References(file,1);await p.Download(file,bytes);
        var raw=Assert.Single(await p.Store.ReadIncludingDeletedAsync(p.Source,Row("id",long.Parse(p.RecordId,CultureInfo.InvariantCulture))));Assert.Equal(Id(Project),SqlRowStore.Text(raw,"yz_project_id"));Assert.Equal(shared,JsonSerializer.Deserialize<string[]>(SqlRowStore.Text(raw,"shared_ids")));Assert.Equal(new[]{Id(First)},JsonSerializer.Deserialize<string[]>(SqlRowStore.Text(raw,"hidden_ids")));Assert.DoesNotContain(raw.Keys,x=>x is "shared_names" or "checked_names" or "tenant_names");Assert.False(added.TryGetProperty("hiddenIds",out _));var page=await p.Post("page",new PageRequest{PageSize=1});Assert.Equal("1",page.GetProperty("total").GetString());
        var before=await p.Snapshot();await p.Post("update",new{id=Id(First+900000),name="越界来源"},HttpStatusCode.InternalServerError);Assert.Equal(before,await p.Snapshot());if(p.ParentScope){await p.Post("update?parentId="+Id(Parent+1),new{id=p.RecordId,name="越界父"},HttpStatusCode.InternalServerError);Assert.Equal(before,await p.Snapshot());}
        foreach(var bad in new object[]{new{id=p.RecordId,sharedIds=new[]{Id(First+2)}},new{id=p.RecordId,checkedIds=new[]{Id(First+2)}},new{id=p.RecordId,tenantIds=new[]{Id(First+10001)}},new{id=p.RecordId,segment=2}}){before=await p.Snapshot();await p.Post("update",bad,HttpStatusCode.InternalServerError);Assert.Equal(before,await p.Snapshot());}
        var echo=JsonSerializer.Deserialize<Dictionary<string,JsonElement>>(added.GetRawText())!;echo["sharedNames"]=JsonSerializer.SerializeToElement(new[]{"伪造名称"});echo["checkedNames"]=JsonSerializer.SerializeToElement(new[]{"伪造复选"});Check(await p.Post("update",echo));before=await p.Snapshot();echo["creating"]=JsonSerializer.SerializeToElement(true);await p.Post("update",echo,HttpStatusCode.BadRequest);Assert.Equal(before,await p.Snapshot());
        await p.Store.UpdateAsync(Shared,First,Row("status",0));try{before=await p.Snapshot();await p.Post("add",new{name="隐藏默认拒绝",segment=1,sharedIds=new[]{Id(First+1)},checkedIds=new[]{Id(First+1)}},HttpStatusCode.InternalServerError);Assert.Equal(before,await p.Snapshot());}finally{await p.Store.UpdateAsync(Shared,First,Row("status",1));}
        // 多选保留来源查询继承；只有来源编辑时，目标query缺失必须阻断多选写。复选仍按来源动作。
        await p.Grant("301","[]");await p.Grant("302","[]");await p.Grant("402","[]");await Selected();await Checkbox();await p.Grant(p.SourcePage,"[\"is_update\",\"is_export\"]");await Selected(HttpStatusCode.Forbidden);await Checkbox();before=await p.Snapshot();await p.Post("update",new{id=p.RecordId,sharedIds=shared},HttpStatusCode.Forbidden);Assert.Equal(before,await p.Snapshot());await p.Post("update",new{id=p.RecordId,checkedIds});await p.Download(file,bytes,HttpStatusCode.Unauthorized);await p.Grant(p.SourcePage,"[\"is_all\"]");await p.Post("importDatas201",new{parentId=p.ParentId,requestJson=new[]{Import("无独立目标查询导入",Original,Second)}});foreach(var id in new[]{"301","302","402"})await p.Grant(id,"[\"is_all\"]");
        var sourceBefore=await SourceRows();name="共享新_%!名称'";await p.Send(p.Owner,HttpMethod.Post,"/api/admin/auto/"+Shared+"/301/update",new{id=Id(First),name});Assert.Equal(sourceBefore,await SourceRows());Check((await p.Send(p.Reader,HttpMethod.Get,p.Route+"detail/"+p.RecordId)).GetProperty("data"));foreach(var key in GlobalMultipleFreshCatalogTests.Definition(p.Profile).Automatic?new[]{"sharedNames"}:new[]{"sharedNames","checkedNames"}){page=await p.Post("page",new PageRequest{PageSize=1,Filters=new(){{key,JsonSerializer.SerializeToElement(name)}}});Assert.Equal("2",page.GetProperty("total").GetString());}
        await p.Post("importDatas201",new{parentId=p.ParentId,requestJson=new[]{Import("当前名称导入",name,Second)}});before=await p.Snapshot();await p.Post("importDatas201",new{parentId=p.ParentId,requestJson=new[]{Import("整批首行",name,Second),Import("整批尾行","不存在",Second)}},HttpStatusCode.BadRequest);Assert.Equal(before,await p.Snapshot());await p.Post("importDatas201",new{parentId=p.ParentId,requestJson=new[]{Import("重名拒绝","重复名",Second)}},HttpStatusCode.BadRequest);Assert.Equal(before,await p.Snapshot());
        var ticket=(await p.Post("initExport",new PageRequest{SelectedIds=[p.RecordId]})).GetString()!;using(var response=await p.Reader.GetAsync(ExportDownloadAccess.DownloadPath+"?exportId="+Uri.EscapeDataString(ticket))){Assert.Equal(HttpStatusCode.OK,response.StatusCode);using var book=new XLWorkbook(new MemoryStream(await response.Content.ReadAsByteArrayAsync()));var sheet=book.Worksheet(1);var headers=sheet.Row(1).CellsUsed().ToDictionary(x=>x.GetString(),x=>x.Address.ColumnNumber);Assert.Equal(new[]{Second,name},JsonSerializer.Deserialize<string[]>(sheet.Row(2).Cell(headers["共享多选"]).GetString()));Assert.Equal(new[]{name,Second},JsonSerializer.Deserialize<string[]>(sheet.Row(2).Cell(headers["共享复选"]).GetString()));}
        // 缺失目标保留原ID和null名称位置；显式重提失效项仍使整个保存失败。
        var sourceSnapshot=await SourceRows();await p.Store.UpdateAsync(Shared,First+1,Row("delete_no",DateTime.UtcNow));try{var missing=(await p.Send(p.Reader,HttpMethod.Get,p.Route+"detail/"+p.RecordId)).GetProperty("data");Assert.Equal(shared,missing.GetProperty("sharedIds").EnumerateArray().Select(x=>x.GetString()));Assert.Equal(JsonValueKind.Null,missing.GetProperty("sharedNames")[0].ValueKind);Assert.Equal(name,missing.GetProperty("sharedNames")[1].GetString());Assert.Equal(JsonValueKind.Null,missing.GetProperty("checkedNames")[1].ValueKind);Assert.Equal(sourceSnapshot,await SourceRows());before=await p.Snapshot();await p.Post("update",new{id=p.RecordId,sharedIds=shared},HttpStatusCode.InternalServerError);Assert.Equal(before,await p.Snapshot());}finally{await p.Store.UpdateAsync(Shared,First+1,Row("delete_no",null));}
        if(p.Profile=="cross7")await LargeCheckbox(p);
        var copy=(await p.Post("copy/"+p.RecordId,new{})).GetProperty("id").GetString()!;await p.References(file,2);var secondBytes=Encoding.UTF8.GetBytes("多值晚期引用");var second=await p.Upload(secondBytes);var constraint="mt_gm_ref_"+Guid.NewGuid().ToString("N")[..12];var installed=false;var late=new{id=p.RecordId,name="晚期来源修改",checkedIds,attachments=new[]{second}};try{await Sql("ALTER TABLE `yz_file_ref` ADD CONSTRAINT `"+constraint+"` CHECK (`file_id` <> "+long.Parse(second,CultureInfo.InvariantCulture).ToString(CultureInfo.InvariantCulture)+")");installed=true;before=await p.Snapshot();await p.Post("update",late,HttpStatusCode.InternalServerError);Assert.Equal(before,await p.Snapshot());await Sql("ALTER TABLE `yz_file_ref` DROP CHECK `"+constraint+"`");installed=false;await p.Post("update",late);await p.References(second,1);await p.References(file,1);await p.Download(second,secondBytes);}finally{if(installed)await Sql("ALTER TABLE `yz_file_ref` DROP CHECK `"+constraint+"`");}
        await p.Post("update",new{id=p.RecordId,sharedIds=(string[]?)null,checkedIds=Array.Empty<string>()});var cleared=(await p.Send(p.Reader,HttpMethod.Get,p.Route+"detail/"+p.RecordId)).GetProperty("data");Assert.Empty(cleared.GetProperty("sharedNames").EnumerateArray());Assert.Empty(cleared.GetProperty("checkedNames").EnumerateArray());await p.Post("update",new{id=p.RecordId,sharedIds=shared,checkedIds});await p.Send(p.Reader,HttpMethod.Delete,p.Route,new{id=copy});await p.References(file,0);await p.References(second,1);await p.Grant(p.SourcePage,"[]");await p.Post("page",new PageRequest(),HttpStatusCode.Forbidden);await Checkbox(HttpStatusCode.Forbidden);await p.Grant(p.SourcePage,"[\"is_all\"]");
        /// <summary>名称与ID都保持原数组顺序，精确区分相邻长整数。</summary>
        void Check(JsonElement row){Assert.Equal(shared,row.GetProperty("sharedIds").EnumerateArray().Select(x=>x.GetString()));Assert.Equal(checkedIds,row.GetProperty("checkedIds").EnumerateArray().Select(x=>x.GetString()));Assert.Equal(new[]{Second,name},row.GetProperty("sharedNames").EnumerateArray().Select(x=>x.GetString()));Assert.Equal(new[]{name,Second},row.GetProperty("checkedNames").EnumerateArray().Select(x=>x.GetString()));}
        /// <summary>目标改名不能回写非冗余来源记录。</summary>
        async Task<string> SourceRows()=>JsonSerializer.Serialize((await p.Store.ReadIncludingDeletedAsync(p.Source)).OrderBy(x=>SqlRowStore.Id(x)));
        /// <summary>中文表头保持原名称JSON数组，范围在来源import事务内反查。</summary>
        static Dictionary<string,object?> Import(string record,string first,string second)=>Row("记录名",record,"共享多选",JsonSerializer.Serialize(new[]{second,first}),"共享复选",JsonSerializer.Serialize(new[]{first,second}),"项目多选",JsonSerializer.Serialize(new[]{"项目候选"}),"分组",1);
        /// <summary>仅在本轮租约库安装／撤销精确CHECK，不授触发器或全局权限。</summary>
        async Task Sql(string sql){await using var c=p.Session.Provider.CreateConnection(p.Session.Options);await c.OpenAsync();await using var command=c.CreateCommand();command.CommandText=sql;await command.ExecuteNonQueryAsync();}
    }
    /// <summary>实际5000候选和全选写入不截断，第5001项明确拒绝；只影响本轮新库。</summary>
    private static async Task LargeCheckbox(Probe p)
    {
        var ids=Enumerable.Range(0,5000).Select(i=>Id(First+100000+i)).ToArray();foreach(var(index,id)in ids.Select((id,index)=>(index,id))){var row=Row("id",long.Parse(id,CultureInfo.InvariantCulture),"name","大候选"+index,"status",1,"segment",3,"score",0m);if(!p.NoProject)row["yz_project_id"]=Project+1;await p.Store.InsertAsync(Shared,row);}var options=await p.Post("findNameIdChecked2204",new{parentId=p.ParentId,formParameters=new{segment=3}});Assert.Equal(5000,options.GetArrayLength());await p.Store.InsertAsync(Shared,Row("id",First+105000,"name","第5001项","status",1,"segment",3,"score",0m));await p.Post("findNameIdChecked2204",new{parentId=p.ParentId,formParameters=new{segment=3}},HttpStatusCode.InternalServerError);var selected=await p.Post("findNameIdChecked2204",new{parentId=p.ParentId,formParameters=new{segment=3},id=new[]{ids[^1]}});Assert.Equal(ids[^1],Assert.Single(selected.EnumerateArray()).GetProperty("id").GetString());var updated=await p.Post("update",new{id=p.RecordId,sharedIds=(string[]?)null,checkedIds=ids,segment=3});Assert.Equal(ids,updated.GetProperty("checkedIds").EnumerateArray().Select(x=>x.GetString()));Assert.Equal(5000,updated.GetProperty("checkedNames").GetArrayLength());await p.Post("update",new{id=p.RecordId,segment=1,sharedIds=new[]{Id(First+1),Id(First)},checkedIds=new[]{Id(First),Id(First+1)}});
    }
}
